namespace ghidra.framework.project.tool;









using docking;
using docking.widgets;
using docking.widgets.button;
using docking.widgets.label;
using ghidra.framework.plugintool;
using ghidra.util;
using ghidra.util.layout;

public class SelectChangedToolDialog : DialogComponentProvider {

	private List<PluginTool> toolList;
	private bool wasCancelled;

	private PluginTool selectedTool;

	public SelectChangedToolDialog(List<PluginTool> toolList) : base("Save Tool Changes?", true, false, true, false)
    {
		this.toolList = toolList;

		addWorkPanel(buildWorkPanel());

		addOKButton();
		addCancelButton();
		Dimension preferredSize = getPreferredSize();
		setPreferredSize(preferredSize.width, Math.min(300, preferredSize.height));
		setRememberLocation(false);
		setRememberSize(false);

	}

	private JPanel buildWorkPanel() {

		JPanel panel = new JPanel(new BorderLayout());

		string toolName = toolList.get(0).getToolName();
		JLabel descriptionLabel = new GHtmlLabel(HTMLUtilities.toHTML(
			"There are multiple changed instances of " + HTMLUtilities.escapeHTML(toolName) +
				" running.<p>Which one would like to save to your tool chest?"));
		descriptionLabel.getAccessibleContext().setAccessibleName("Description");
		descriptionLabel.setIconTextGap(15);
		descriptionLabel.setIcon(OptionDialog.getIconForMessageType(OptionDialog.WARNING_MESSAGE));
		descriptionLabel.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		panel.add(descriptionLabel, BorderLayout.NORTH);
		JScrollPane scrollPane = new JScrollPane(buildRadioButtonPanel());
		scrollPane.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		scrollPane.getAccessibleContext().setAccessibleName("Radio Button");
		panel.add(scrollPane);
		panel.getAccessibleContext().setAccessibleName("Select Changed Tool");
		return panel;
	}

	private JPanel buildRadioButtonPanel() {
		JPanel panel = new JPanel(new VerticalLayout(5));

		ButtonGroup buttonGroup = new ButtonGroup();

		GRadioButton noneButton = new GRadioButton("None");
		noneButton.getAccessibleContext().setAccessibleName("None");
		ItemListener listener = new _Anon_ItemListener_1();
		noneButton.addItemListener(listener);
		buttonGroup.add(noneButton);
		panel.add(noneButton);

		foreach (PluginTool tool in toolList) {
			GRadioButton radioButton = new GRadioButton(tool.getName());
			radioButton.getAccessibleContext().setAccessibleName(tool.getToolName());
			radioButton.addItemListener(new _Anon_ItemListener_2());
			buttonGroup.add(radioButton);
			panel.add(radioButton);
		}

		buttonGroup.setSelected(noneButton.getModel(), true);
		panel.getAccessibleContext().setAccessibleName("Tool Selection Button");
		return panel;
	}

	/* @Override */
	protected void cancelCallback() {
		base.cancelCallback();
		wasCancelled = true;
	}

	/* @Override */
	protected void okCallback() {
		close();
	}

	bool wasCancelled() {
		return wasCancelled;
	}

	PluginTool getSelectedTool() {
		return selectedTool;
	}

	internal class _Anon_ItemListener_1 : ItemListener
	{

			/* @Override */
			public void itemStateChanged(ItemEvent e) {
				selectedTool = null;
			}
		
	}


	internal class _Anon_ItemListener_2 : ItemListener
	{

				/* @Override */
				public void itemStateChanged(ItemEvent e) {
					selectedTool = tool;
				}
			
	}

}
